// The bundled MITRE CWE catalog (cwe-catalog.json next to this file, regenerated by
// tools/cwe/build-cwe-catalog.mjs). Answers in the shape the Find CWE page, the CSAF
// editor and the VEX export already read: {data: {matches, 1: record}}.
//
// CommonJS with no meteor/* imports so Jest can require it directly. Server-only: the
// catalog never reaches the client bundle.
const catalog = require('./cwe-catalog.json');

// '79', 'CWE-79', 'cwe 79', 'CWE:79' -> '79'. A trailing '*' (the wildcard syntax the
// search box still advertises) is ignored: entries are looked up by exact id only.
const CWE_ID = /^(?:cwe[-_:\s]*)?(\d{1,6})\s*\*?$/i;
const INPUT_MAX = 20;

function cweNumber(value) {
  if (typeof value !== 'string' && typeof value !== 'number') {
    return '';
  }
  const str = String(value).trim();
  if (str.length > INPUT_MAX) {
    return '';
  }
  const match = CWE_ID.exec(str);
  return match ? String(Number(match[1])) : '';
}

function lookupCwe(value) {
  const id = cweNumber(value);
  const record = id && Object.prototype.hasOwnProperty.call(catalog.cwes, id) ? catalog.cwes[id] : null;
  if (!record) {
    return {statusCode: 200, data: {matches: 0}};
  }
  return {statusCode: 200, data: {matches: 1, 1: Object.assign({}, record)}};
}

module.exports = {lookupCwe, cweNumber};
